 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0 for _ in range(w)] for _ in range(h)]
    barrier = next((r for r, row in enumerate(grid) if row and all(v == 2 for v in row)), None)
    if barrier is None:
        return [row[:] for row in grid]
    # Keep the divider and all objects below it unchanged.
    for r in range(barrier, h):
        out[r] = grid[r][:]
    # Objects above the divider fall one cell. Those landing immediately above
    # the divider produce diagonal rays spreading upward from the landing point.
    for r in range(barrier):
        for c, value in enumerate(grid[r]):
            if value != 4:
                continue
            nr = r + 1
            if nr == barrier - 1:
                out[nr][c] = 4
                for d in range(1, max(h, w) + 1):
                    rr = nr - d
                    if rr < 0:
                        break
                    if c - d >= 0:
                        out[rr][c - d] = 4
                    if c + d < w:
                        out[rr][c + d] = 4
            else:
                out[nr][c] = 4
    return out
